const ICHING_HEXAGRAMS = [{n: 1, cn: "乾", name: "The Creative", pattern: "111111", blurb: "Pure yang. Sustained creative force, driving forward without pause."},{n: 2, cn: "坤", name: "The Receptive", pattern: "000000", blurb: "Pure yin. Yielding, supportive, gets things done by not forcing them."},{n: 3, cn: "屯", name: "Difficulty at the Beginning", pattern: "010001", blurb: "A new thing struggling to take its first shape. Chaotic, not doomed."},{n: 4, cn: "蒙", name: "Youthful Folly", pattern: "100010", blurb: "Inexperience asking the wrong question, or the right one badly."},{n: 5, cn: "需", name: "Waiting", pattern: "010111", blurb: "The moment isn't ready yet. Waiting well is its own skill."},{n: 6, cn: "訟", name: "Conflict", pattern: "111010", blurb: "A dispute with no clean winner. Better settled early than escalated."},{n: 7, cn: "師", name: "The Army", pattern: "000010", blurb: "Organized collective effort under one clear line of command."},{n: 8, cn: "比", name: "Holding Together", pattern: "010000", blurb: "Alliance and mutual support. Works only if it starts honestly."},{n: 9, cn: "小畜", name: "Small Taming", pattern: "110111", blurb: "Small, patient restraint. Gathering strength before it's dramatic."},{n: 10, cn: "履", name: "Treading", pattern: "111011", blurb: "Careful footing around something dangerous. Conduct matters here."},{n: 11, cn: "泰", name: "Peace", pattern: "000111", blurb: "Heaven and earth in easy exchange. Things flow, for now."},{n: 12, cn: "否", name: "Standstill", pattern: "111000", blurb: "Communication has broken down. Withdraw and wait it out."},{n: 13, cn: "同人", name: "Fellowship", pattern: "111101", blurb: "Genuine common cause with others, out in the open."},{n: 14, cn: "大有", name: "Great Possession", pattern: "101111", blurb: "Real abundance, held with a light hand instead of a tight fist."},{n: 15, cn: "謙", name: "Modesty", pattern: "000100", blurb: "Quiet competence that doesn't need to announce itself."},{n: 16, cn: "豫", name: "Enthusiasm", pattern: "001000", blurb: "Momentum and morale, spreading outward from one confident source."},{n: 17, cn: "隨", name: "Following", pattern: "011001", blurb: "Adapting to what's actually happening instead of the plan."},{n: 18, cn: "蠱", name: "Work on the Decayed", pattern: "100110", blurb: "Something's gone quietly wrong and needs real repair, not a patch."},{n: 19, cn: "臨", name: "Approach", pattern: "000011", blurb: "Influence on the rise. What you do now sets the tone."},{n: 20, cn: "觀", name: "Contemplation", pattern: "110000", blurb: "Stepping back to actually see the pattern, not just the moment."},{n: 21, cn: "噬嗑", name: "Biting Through", pattern: "101001", blurb: "An obstacle that has to be dealt with directly, not around."},{n: 22, cn: "賁", name: "Grace", pattern: "100101", blurb: "Surface and style - useful, but not a substitute for substance."},{n: 23, cn: "剝", name: "Splitting Apart", pattern: "100000", blurb: "Erosion from the bottom up. Don't fight it, just don't feed it."},{n: 24, cn: "復", name: "Return", pattern: "000001", blurb: "A turning point after decline. Small, but the direction has flipped."},{n: 25, cn: "无妄", name: "Innocence", pattern: "111001", blurb: "Acting without an ulterior motive. Forcing an outcome here backfires."},{n: 26, cn: "大畜", name: "Great Taming", pattern: "100111", blurb: "Large, deliberate restraint - power held in reserve on purpose."},{n: 27, cn: "頤", name: "Mouth Corners", pattern: "100001", blurb: "What you take in and what you say. Nourishment, in both senses."},{n: 28, cn: "大過", name: "Great Preponderance", pattern: "011110", blurb: "Load past what the structure was built for. Something has to give."},{n: 29, cn: "坎", name: "The Abysmal", pattern: "010010", blurb: "Repeated danger, water finding the low ground. Stay honest, keep moving."},{n: 30, cn: "離", name: "The Clinging", pattern: "101101", blurb: "Fire needs fuel to keep burning - brightness that depends on attachment."},{n: 31, cn: "咸", name: "Influence", pattern: "011100", blurb: "Mutual attraction, unforced. Something is drawing two things together."},{n: 32, cn: "恆", name: "Duration", pattern: "001110", blurb: "What holds steady over time, through change rather than despite it."},{n: 33, cn: "遯", name: "Retreat", pattern: "111100", blurb: "A strategic withdrawal while there's still room to choose the terms."},{n: 34, cn: "大壯", name: "Great Power", pattern: "001111", blurb: "Strength at full force. Correct use matters more than raw amount."},{n: 35, cn: "晉", name: "Progress", pattern: "101000", blurb: "Advancement in plain daylight, recognized as it happens."},{n: 36, cn: "明夷", name: "Darkening of the Light", pattern: "000101", blurb: "Brightness under cover, kept quiet on purpose to survive a dark spell."},{n: 37, cn: "家人", name: "The Family", pattern: "110101", blurb: "The small unit that everything larger is actually built out of."},{n: 38, cn: "睽", name: "Opposition", pattern: "101011", blurb: "Two things pointed in different directions, close enough to keep colliding."},{n: 39, cn: "蹇", name: "Obstruction", pattern: "010100", blurb: "The direct route is blocked. Circling around beats walking through it."},{n: 40, cn: "解", name: "Deliverance", pattern: "001010", blurb: "Tension finally releasing. Don't relitigate what just got resolved."},{n: 41, cn: "損", name: "Decrease", pattern: "100011", blurb: "Giving something up now that pays off somewhere else later."},{n: 42, cn: "益", name: "Increase", pattern: "110001", blurb: "Resources flowing downward to where they're actually needed."},{n: 43, cn: "夬", name: "Breakthrough", pattern: "011111", blurb: "A decisive break with what's been building. Say it plainly."},{n: 44, cn: "姤", name: "Coming to Meet", pattern: "111110", blurb: "An unplanned encounter that's about to change the equation."},{n: 45, cn: "萃", name: "Gathering Together", pattern: "011000", blurb: "People or forces converging around a shared center."},{n: 46, cn: "升", name: "Pushing Upward", pattern: "000110", blurb: "Gradual, earned ascent - no shortcuts, but it does add up."},{n: 47, cn: "困", name: "Oppression", pattern: "011010", blurb: "Boxed in and running low. What you say now still counts."},{n: 48, cn: "井", name: "The Well", pattern: "010110", blurb: "A resource that stays good regardless of who draws from it."},{n: 49, cn: "革", name: "Revolution", pattern: "011101", blurb: "A real break with the old order, timed right instead of rushed."},{n: 50, cn: "鼎", name: "The Cauldron", pattern: "101110", blurb: "Raw material transformed into something that actually nourishes."},{n: 51, cn: "震", name: "The Arousing", pattern: "001001", blurb: "A shock that startles first and clarifies second."},{n: 52, cn: "艮", name: "Keeping Still", pattern: "100100", blurb: "Stopping cleanly, right where you are, without dragging your feet."},{n: 53, cn: "漸", name: "Development", pattern: "110100", blurb: "Slow, correct-order progress. Skipping steps here costs more later."},{n: 54, cn: "歸妹", name: "The Marrying Maiden", pattern: "001011", blurb: "A subordinate position entered with eyes open, not by accident."},{n: 55, cn: "豐", name: "Abundance", pattern: "001101", blurb: "A peak moment, bright and full - notice it while it's here."},{n: 56, cn: "旅", name: "The Wanderer", pattern: "101100", blurb: "A stranger passing through. Tread carefully, nothing here is yours yet."},{n: 57, cn: "巽", name: "The Gentle", pattern: "110110", blurb: "Influence like wind - no force, but it gets everywhere eventually."},{n: 58, cn: "兌", name: "The Joyous", pattern: "011011", blurb: "Open, genuine pleasure, shared rather than kept to yourself."},{n: 59, cn: "渙", name: "Dispersion", pattern: "110010", blurb: "Something rigid finally breaking up and spreading out."},{n: 60, cn: "節", name: "Limitation", pattern: "010011", blurb: "Useful boundaries - too few and it scatters, too many and it snaps."},{n: 61, cn: "中孚", name: "Inner Truth", pattern: "110011", blurb: "Sincerity that reaches people before any argument does."},{n: 62, cn: "小過", name: "Small Preponderance", pattern: "001100", blurb: "Small, careful overcorrection. Not the moment for grand gestures."},{n: 63, cn: "既濟", name: "After Completion", pattern: "010101", blurb: "Everything in place - which is exactly when it starts to slip."},{n: 64, cn: "未濟", name: "Before Completion", pattern: "101010", blurb: "Not finished yet, close enough to see the shape of the end."}, ];